#!/usr/bin/env python3
# Piece 4-A - List reads go binder-native (adapter at the API layer).
import base64, sys, os
PATH = "lib/vendor/api/vendor.ts"
def d(s): return base64.b64decode(s).decode("utf-8")
EDITS = [
    ("CabinetBinder +created_at", "ICBmb2xsb3d1cF9vbjogc3RyaW5nIHwgbnVsbDsKICBmb2xsb3d1cF9ub3RlOiBzdHJpbmcgfCBudWxsOwogIHBob25lOiBzdHJpbmcgfCBudWxsOwp9Ow==", "ICBmb2xsb3d1cF9vbjogc3RyaW5nIHwgbnVsbDsKICBmb2xsb3d1cF9ub3RlOiBzdHJpbmcgfCBudWxsOwogIHBob25lOiBzdHJpbmcgfCBudWxsOwogIGNyZWF0ZWRfYXQ/OiBzdHJpbmcgfCBudWxsOwp9Ow=="),
    ("insert binder adapters", "ZXhwb3J0IGZ1bmN0aW9uIGZldGNoQ2FiaW5ldCh2ZW5kb3JJZDogc3RyaW5nKTogUHJvbWlzZTxDYWJpbmV0UmVzcG9uc2U+IHsKICByZXR1cm4gZ2V0SnNvbjxDYWJpbmV0UmVzcG9uc2U+KGAvYXBpL3YyL3ZlbmRvci9jYWJpbmV0LyR7dmVuZG9ySWR9YCk7Cn0=", ""),
    ("fetchLeads -> adapter", "", ""),
    ("fetchClients -> adapter", "ZXhwb3J0IGZ1bmN0aW9uIGZldGNoQ2xpZW50cyh2ZW5kb3JJZDogc3RyaW5nKTogUHJvbWlzZTxDbGllbnRzUmVzcG9uc2U+IHsKICBpZiAoVVNFX01PQ0tTKSByZXR1cm4gUHJvbWlzZS5yZXNvbHZlKGdldE1vY2tDbGllbnRzKCkpOwogIHJldHVybiBnZXRKc29uPENsaWVudHNSZXNwb25zZT4oYC9hcGkvdjIvdmVuZG9yL2NsaWVudHMvJHt2ZW5kb3JJZH1gKTsKfQ==", ""),
    ("fetchInvoices -> adapter", "", ""),
    ("fetchExpenses -> adapter", "ZXhwb3J0IGZ1bmN0aW9uIGZldGNoRXhwZW5zZXModmVuZG9ySWQ6IHN0cmluZyk6IFByb21pc2U8RXhwZW5zZXNSZXNwb25zZT4gewogIGlmIChVU0VfTU9DS1MpIHJldHVybiBQcm9taXNlLnJlc29sdmUoZ2V0TW9ja0V4cGVuc2VzKCkpOwogIHJldHVybiBnZXRKc29uPEV4cGVuc2VzUmVzcG9uc2U+KGAvYXBpL3YyL3ZlbmRvci9leHBlbnNlcy8ke3ZlbmRvcklkfWApOwp9", "")
]
if not os.path.exists(PATH):
    print("FATAL: %s not found (run from dreamos-pwa root)." % PATH); sys.exit(1)
text = open(PATH, encoding="utf-8").read()
applied = skipped = 0
for label, o_b64, n_b64 in EDITS:
    old, new = d(o_b64), d(n_b64)
    if new in text:
        print("SKIP  [%s] already applied." % label); skipped += 1; continue
    c = text.count(old)
    if c == 1: text = text.replace(old, new); applied += 1; print("OK    [%s]" % label)
    elif c == 0: print("SKIP  [%s] anchor NOT FOUND - untouched." % label); skipped += 1
    else: print("SKIP  [%s] anchor x%d - untouched." % (label, c)); skipped += 1
open(PATH, "w", encoding="utf-8").write(text)
NEEDLE_L = "getJson<LeadsResponse>(" + chr(96) + "/api/v2/vendor/leads/"
NEEDLE_C = "getJson<ClientsResponse>(" + chr(96) + "/api/v2/vendor/clients/"
NEEDLE_I = "getJson<InvoicesResponse>(" + chr(96) + "/api/v2/vendor/invoices/"
NEEDLE_E = "getJson<ExpensesResponse>(" + chr(96) + "/api/v2/vendor/expenses/"
checks = [
    ("created_at on CabinetBinder", "created_at?: string | null;" in text),
    ("fetchLedger added",          "export function fetchLedger" in text),
    ("binder->client mapper",      "function binderToClient" in text),
    ("binder->lead mapper",        "function binderToLead" in text),
    ("binder->invoice mapper",     "function binderToInvoice" in text),
    ("binder->expense mapper",     "function binderToExpense" in text),
    ("fetchLeads via cabinet",     "const cab = await fetchCabinet(vendorId);" in text and "(cab.leads ?? [])" in text),
    ("fetchExpenses via ledger",   "fetchLedger(vendorId)" in text and "b.direction === " + chr(39) + "out" + chr(39) in text),
    ("dead /leads read gone",      NEEDLE_L not in text),
    ("dead /clients read gone",    NEEDLE_C not in text),
    ("dead /invoices read gone",   NEEDLE_I not in text),
    ("dead /expenses read gone",   NEEDLE_E not in text),
    ("mocks preserved",            "getMockLeads()" in text and "getMockClients()" in text),
]
print(chr(10) + "-- verification --")
allok = True
for n,p in checks: print("  %s %s" % ("PASS" if p else "FAIL", n)); allok = allok and p
print(chr(10) + "(%d applied, %d skipped)" % (applied, skipped))
print("ALL CHECKS PASSED" if allok else "SOME CHECKS FAILED")
sys.exit(0 if allok else 2)
